      }
    ]
  },

  "connectionId": "<YOUR_CONNECTION_ID>",
  "folderKey": "<YOUR_FOLDER_KEY>",

  "eventMode": "polling",

  "eventParameters": {
    "parentFolderId": "<INBOX_FOLDER_ID_OR_OMIT_FOR_DEFAULT_INBOX>"
  },

